        // The Out variant is the time/value-mirrored In variant: easeOut(t) == 1 - easeIn(1-t).
        void EasingOutMirrorsIn()
        {
            var inQ = new doubleEasing.EaseInQuad();
            var outQ = new doubleEasing.EaseOutQuad();
            var inC = new doubleEasing.EaseInCubic();
            var outC = new doubleEasing.EaseOutCubic();
            var inK = new doubleEasing.EaseInQuart();
            var outK = new doubleEasing.EaseOutQuart();
            var inS = new doubleEasing.EaseInSine();
            var outS = new doubleEasing.EaseOutSine();

            for (int k = 0; k <= 10; k++)
            {
                double t = (double)k / (double)10;
                AssertClose(outQ.Eval(t), (double)1 - inQ.Eval((double)1 - t), 1E-5f);
                AssertClose(outC.Eval(t), (double)1 - inC.Eval((double)1 - t), 1E-5f);
                AssertClose(outK.Eval(t), (double)1 - inK.Eval((double)1 - t), 1E-5f);
                AssertClose(outS.Eval(t), (double)1 - inS.Eval((double)1 - t), 1E-5f);
            }
        }

        // 1D Gaussian: sums to 1, symmetric, peak at center.
        void GaussianKernel()
        {
            var arena = new Arena(Allocator.Persistent);

            int N = 5;
            var g = arena.doubleVec(N);
            Generate.gaussianKernel(ref g, (double)1);

            double sum = (double)0;
            for (int i = 0; i < N; i++) sum += g[i];
            AssertClose(sum, (double)1f, 1E-5f);

            // symmetric
            for (int i = 0; i < N; i++)
                AssertClose(g[i], g[N - 1 - i], 1E-5f);

            // center is the strict max
            AssertTrue(g[2] > g[1]);
            AssertTrue(g[1] > g[0]);

            // N==1 -> {1}
            var one = arena.doubleVec(1);
            Generate.gaussianKernel(ref one, (double)2);
            AssertClose(one[0], (double)1f, 1E-6f);

            arena.Dispose();
        }

        // Box: every weight 1/N (sum 1). Tent: symmetric, sums to 1, peak at center.
        void BoxTentKernel()
        {
            var arena = new Arena(Allocator.Persistent);

            int N = 6;
            var box = arena.doubleVec(N);
            Generate.boxKernel(ref box);
            double bsum = (double)0;
            for (int i = 0; i < N; i++)
            {
                AssertClose(box[i], (double)1 / (double)N, 1E-6f);
                bsum += box[i];
            }
            AssertClose(bsum, (double)1f, 1E-5f);

            int M = 5;
            var tent = arena.doubleVec(M);
            Generate.tentKernel(ref tent);
            double tsum = (double)0;
            for (int i = 0; i < M; i++) tsum += tent[i];
            AssertClose(tsum, (double)1f, 1E-5f);
            for (int i = 0; i < M; i++)
                AssertClose(tent[i], tent[M - 1 - i], 1E-5f);
            AssertTrue(tent[2] > tent[1]);
            AssertTrue(tent[1] > tent[0]);

            arena.Dispose();
        }

        // Hann/Hamming/Blackman/Box known endpoint and center values (N=5, denom 4).
        void Windows()
        {
            var arena = new Arena(Allocator.Persistent);

            int N = 5;

            var hann = arena.doubleVec(N);
            Generate.window(ref hann, WindowType.Hann);
            AssertClose(hann[0], (double)0f, 1E-5f);
            AssertClose(hann[4], (double)0f, 1E-5f);
            AssertClose(hann[2], (double)1f, 1E-5f); // 0.5(1-cos π) = 1
            AssertClose(hann[1], hann[3], 1E-5f);    // symmetric

            var hamming = arena.doubleVec(N);
            Generate.window(ref hamming, WindowType.Hamming);
            AssertClose(hamming[0], (double)0.08f, 1E-5f);
            AssertClose(hamming[4], (double)0.08f, 1E-5f);
            AssertClose(hamming[2], (double)1f, 1E-5f); // 0.54+0.46 = 1

            var black = arena.doubleVec(N);
            Generate.window(ref black, WindowType.Blackman);
            AssertClose(black[0], (double)0f, 1E-5f);  // 0.42-0.5+0.08 = 0
            AssertClose(black[4], (double)0f, 1E-5f);
            AssertClose(black[2], (double)1f, 1E-5f);  // 0.42+0.5+0.08 = 1 (center)
            AssertClose(black[1], black[3], 1E-5f);    // symmetric

            var box = arena.doubleVec(N);
            Generate.window(ref box, WindowType.Box);
            for (int i = 0; i < N; i++)
                AssertClose(box[i], (double)1f, 1E-6f);

            // N==1 -> {1} for the (N-1)-denominator windows (no div-by-zero)
            var one = arena.doubleVec(1);
            Generate.window(ref one, WindowType.Hann);
            AssertClose(one[0], (double)1f, 1E-6f);

            arena.Dispose();
        }

        // outer[i,j] == u[i]*v[j]; outerSum[i,j] == u[i]+v[j].
        void OuterAndOuterSum()
        {
            var arena = new Arena(Allocator.Persistent);

            var u = arena.doubleVec(3);
            u[0] = 1f; u[1] = 2f; u[2] = 3f;
            var v = arena.doubleVec(2);
            v[0] = 4f; v[1] = 5f;

            var O = arena.doubleMat(3, 2);
            Generate.outer(in u, in v, ref O);

            var S = arena.doubleMat(3, 2);
            Generate.outerSum(in u, in v, ref S);

            for (int i = 0; i < 3; i++)
                for (int j = 0; j < 2; j++)
                {
                    AssertClose(O[i, j], u[i] * v[j], 1E-5f);
                    AssertClose(S[i, j], u[i] + v[j], 1E-5f);
                }

            arena.Dispose();
        }

        // gaussianKernel2D == outer(g,g) of the 1D Gaussian: separable, sums to 1, symmetric.
        void GaussianKernel2D()
        {
            var arena = new Arena(Allocator.Persistent);

            int N = 5;
            double sigma = (double)1.2;

            var g = arena.doubleVec(N);
            Generate.gaussianKernel(ref g, sigma);

            var K = arena.doubleMat(N, N);
            Generate.gaussianKernel2D(ref K, sigma);

            double sum = (double)0;
            for (int i = 0; i < N; i++)
                for (int j = 0; j < N; j++)
                {
                    AssertClose(K[i, j], g[i] * g[j], 1E-5f); // separable
                    sum += K[i, j];
                }
            AssertClose(sum, (double)1f, 1E-4f); // (Σg)² = 1

            // symmetric both ways
            AssertClose(K[0, 4], K[4, 0], 1E-6f);
            AssertClose(K[1, 3], K[3, 1], 1E-6f);

            arena.Dispose();
        }

        // Sine/Saw/Square/Triangle at canonical phase points over one cycle.
        void Waves()
        {
            var sine = new doubleWave.Sine { Cycles = (double)1 };
            AssertClose(sine.Eval((double)0), (double)0f, 1E-5f);
            AssertClose(sine.Eval((double)0.25), (double)1f, 1E-5f);
            AssertClose(sine.Eval((double)0.5), (double)0f, 1E-5f);
            AssertClose(sine.Eval((double)0.75), (double)(-1f), 1E-5f);

            var saw = new doubleWave.Saw { Cycles = (double)1 };
            AssertClose(saw.Eval((double)0), (double)(-1f), 1E-5f);
            AssertClose(saw.Eval((double)0.5), (double)0f, 1E-5f);

            var sq = new doubleWave.Square { Cycles = (double)1, Duty = (double)0.5 };
            AssertClose(sq.Eval((double)0.25), (double)1f, 1E-6f);
            AssertClose(sq.Eval((double)0.75), (double)(-1f), 1E-6f);

            var tri = new doubleWave.Triangle { Cycles = (double)1 };
            AssertClose(tri.Eval((double)0), (double)(-1f), 1E-5f);
            AssertClose(tri.Eval((double)0.25), (double)0f, 1E-5f);
            AssertClose(tri.Eval((double)0.5), (double)1f, 1E-5f);

            // default-constructed Sine uses Cycles=1 (the 0->1 fallback)
            var def = new doubleWave.Sine();
            AssertClose(def.Eval((double)0.25), (double)1f, 1E-5f);

            // Cycles != 1: a 2-cycle sine peaks at t=0.125 (quarter of the first of two periods).
            var two = new doubleWave.Sine { Cycles = (double)2 };
            AssertClose(two.Eval((double)0.125), (double)1f, 1E-5f);
            AssertClose(two.Eval((double)0.25), (double)0f, 1E-5f); // sin(π)

            // Phase shift: a quarter-period phase turns sin into cos, so Eval(0) == 1.
            var ph = new doubleWave.Sine { Cycles = (double)1, Phase = (double)0.25 };
            AssertClose(ph.Eval((double)0), (double)1f, 1E-5f);
        }

